/*
 * codegen.c -- small canned snippets for Python, JavaScript, HTML and CSS.
 *
 * Nothing is generated by a model here; every snippet is written out by hand
 * and picked by keyword overlap, in the same spirit as the chat script itself.
 * It only fires when the user clearly asks for code, so ordinary chat is
 * untouched.
 */
#include <stdio.h>
#include <string.h>
#include <ctype.h>

#include "codegen.h"

#define MAX_CODE_LINES 32

typedef struct {
    const char *keys;   /* space separated words/phrases that select this snippet */
    const char *title;
    const char *code[MAX_CODE_LINES];
} Snippet;

typedef struct {
    const char *name;     /* canonical name, printed in the code fence */
    const char *label;    /* pretty name, printed in the sentence */
    const char *aliases;  /* words in the input that select this language */
    const char *menu;     /* what to list when we do not know the topic */
    const Snippet *snips;
} Lang;

