/* Words that tell us the user wants code rather than conversation. */
static const char *REQUEST_WORDS[] = {
    "make", "write", "give", "show", "create", "generate", "build", "code",
    "snippet", "example", "how do i", "how to", "teach me", "need", "want",
    "help me with", NULL
};

/* ---------------------------------------------------------------- helpers */

/*
 * Word aware search: does `needle` (one word, or a phrase) appear in `hay`
 * on word boundaries? `hay` is already lower case with single spaces.
 */
static int has_phrase(const char *hay, const char *needle)
{
    size_t nlen = strlen(needle);
    const char *p = hay;

    while ((p = strstr(p, needle)) != NULL) {
        int left_ok  = (p == hay) || (p[-1] == ' ');
        char after   = p[nlen];
        int right_ok = (after == '\0' || after == ' ');
        if (left_ok && right_ok)
            return 1;
        p += 1;
    }
    return 0;
}

/* Count how many of a space separated key list appear in the input. */
static int score_keys(const char *input, const char *keys)
{
    char word[64];
    size_t w = 0;
    int score = 0;

    for (const char *p = keys;; p++) {
        if (*p != ' ' && *p != '\0') {
            if (w + 1 < sizeof word)
                word[w++] = *p;
            continue;
        }
        word[w] = '\0';
        if (w > 0 && has_phrase(input, word))
            score++;
        w = 0;
        if (*p == '\0')
            break;
    }
    return score;
}

static void app(char *out, size_t outsz, const char *s)
{
    size_t n = strlen(out);
    if (n + 1 >= outsz)
        return;
    snprintf(out + n, outsz - n, "%s", s);
}

static const Lang *find_lang(const char *input)
{
    for (const Lang *l = LANGS; l->name; l++) {
        char alias[32];
        size_t w = 0;
        for (const char *p = l->aliases;; p++) {
            if (*p != ' ' && *p != '\0') {
                if (w + 1 < sizeof alias)
                    alias[w++] = *p;
                continue;
            }
            alias[w] = '\0';
            if (w > 0 && has_phrase(input, alias))
                return l;
            w = 0;
            if (*p == '\0')
                break;
        }
    }
    return NULL;
}

static int wants_code(const char *input)
{
    for (const char **r = REQUEST_WORDS; *r; r++)
        if (has_phrase(input, *r))
            return 1;
    return 0;
}

static void emit(const Lang *lang, const Snippet *s, int lead,
                 char *out, size_t outsz)
{
    char line[256];

    if (lead) {
        snprintf(line, sizeof line, "Certainly. Here is a little %s to %s:\n\n",
                 lang->label, s->title);
        app(out, outsz, line);
    }

    snprintf(line, sizeof line, "--- %s ---\n", lang->name);
    app(out, outsz, line);

    for (const char *const *c = s->code; *c; c++) {
        app(out, outsz, *c);
        app(out, outsz, "\n");
    }

    app(out, outsz, "--- end ---");
}

/* ------------------------------------------------------------------- api */

void codegen_usage(char *out, size_t outsz)
{
    out[0] = '\0';
    app(out, outsz,
        "I can write small pieces of Python, JavaScript, HTML and CSS.\n"
        "Just ask in plain words, for example:\n\n"
        "  make me a button in css\n"
        "  write hello world in py\n"
        "  show me a loop in javascript\n"
        "  give me a form in html\n\n"
        "Or be explicit:  /code css dark mode\n"
        "Everything else I hear, I will simply talk with you about.");
}

int codegen_try(const char *input, char *out, size_t outsz)
{
    const Lang *lang;
    const Snippet *best = NULL;
    int best_score = 0;
    int explicit_cmd = 0;

    if (input == NULL || input[0] == '\0')
        return 0;

    /* "/code ..." always means business. */
    if (strncmp(input, "code ", 5) == 0 || strcmp(input, "code") == 0)
        explicit_cmd = 1;

    lang = find_lang(input);
    if (lang == NULL) {
        if (explicit_cmd) {
            out[0] = '\0';
            codegen_usage(out, outsz);
            return 1;
        }
        return 0;
    }

    if (!explicit_cmd && !wants_code(input))
        return 0;

    for (const Snippet *s = lang->snips; s->keys; s++) {
        int score = score_keys(input, s->keys);
        if (score > best_score) {
            best_score = score;
            best = s;
        }
    }

    out[0] = '\0';

    if (best == NULL) {
        char line[512];
        snprintf(line, sizeof line,
                 "I am not sure which piece of %s you want, so here is a "
                 "starting point:\n\n", lang->label);
        app(out, outsz, line);
        emit(lang, &lang->snips[0], 0, out, outsz);

        snprintf(line, sizeof line,
                 "\n\nIn %s I can also show you: %s.\nAsk me for any of those.",
                 lang->label, lang->menu);
        app(out, outsz, line);
        return 1;
    }

    emit(lang, best, 1, out, outsz);
    app(out, outsz,
        "\n\nNow, where were we? Tell me more about what you were saying.");
    return 1;
}
